// OPER621 Business Process Management · Week 1 · Fundamentals of Process Management.
// Source: Week 1 Session 1 slides, Week 1 Delivery Plan, Week 1 forum case (Moodle course 447), Jeston ch. 1–2.
// Each section is a list of [spoken sentence, visual moment(s)]: one moment per sentence, so voice and picture stay in step.
// Writing rule (Prof. Jarboui): write for human brains, not AI. Full sentences that give the reason ("because…"),
// a concrete example for every idea, one running story (the Qasr hotel guest). Diagram boxes may be short labels,
// but every diagram has a caption that says in a full sentence what the picture shows.
// `sec` links a section to the question-bank section it teaches (see adaptive.js).
(() => {
  const D = window.DIAG;
  const t = (kicker, text, count) => ({ type: "title", kicker, text, count });
  const it = (n, of, icon, title, text) => ({ type: "item", n, of, icon, title, text });
  const q = (text) => ({ type: "question", text });
  const st = (text) => ({ type: "statement", text });
  const iss = (text, effect) => ({ type: "issue", text, effect });
  const cmp = (side, label, note, dir) => ({ type: "compare", side, label, note, dir });
  const dg = (kicker, svg, caption) => ({ type: "diagram", kicker, svg, caption });
  const fm = (label, num, den) => ({ type: "formula", label, num, den });
  window.MOMENT_KIT = { t, it, q, st, iss, cmp, dg, fm };

  const hierRows = [["Value chain", "Serve the guest"], ["Process", "Check a guest in"], ["Sub-process", "Verify the booking"], ["Activity", "Check rate and guarantee"], ["Task", "Open the corporate portal"]];
  const exhibit = [["Queue at desk", 6, false], ["Find booking in 2 systems", 4, false], ["Re-key guest details", 3, false], ["Call revenue office", 7, false], ["Confirm room released", 2, false], ["Hand over key", 1, true]];

  window.COURSE = {
    id: "oper621-w1",
    code: "OPER621",
    title: "Fundamentals of Process Management",
    subtitle: "Business Process Management · Week 1",
    author: "Prof. Bassem Jarboui",
    teacher: { name: "Prof. Bassem Jarboui", email: "", sendReport: false },
    lessons: [
      {
        id: "l1",
        title: "What a process really is",
        sections: [
{
title: "Welcome to Week 1",
lines: [
["Welcome to Business Process Management, and I'm glad you're joining me for this first week.", t("OPER621 · Week 1", "Fundamentals of Process Management")],
["Before we open a textbook, I'd like you to imagine arriving at a hotel after a long journey.", null],
["You're tired, you've been travelling for hours, and all you want is to reach your room.", q("What would a tired guest really want from the hotel?")],
["The receptionist smiles, welcomes you warmly, and begins checking your reservation.", null],
["But something isn't quite right, because the booking information doesn't match what appears on her screen.", dg("A guest's difficult arrival", D.flow(["Guest|arrives", "Front|desk", "Reservations", "Revenue|office", "!Guest|waits"]), "The guest has arrived, but several departments must exchange information before check-in can continue.")],
["She calls another department, waits for an answer, and then asks you to confirm information you've already provided.", null],
["Nobody is being rude, and nobody seems unwilling to help you.", st("Every employee can be helpful while the guest's problem remains unresolved.")],
["In fact, each employee may be doing their own job exactly as instructed.", null],
["Yet you're still standing there, wondering why something so simple has become so complicated.", iss("The employees are doing their jobs, but the guest is still waiting.", "A frustrating experience")],
["Now pause for a second and ask yourself something important about this situation.", null],
["If everyone is doing their job properly, why isn't the customer getting what they need?", q("How can everyone do their job correctly while the customer still suffers?")],
["That's the question I want you to carry with you throughout this course.", null],
["Because organisations don't succeed simply by having excellent departments; they succeed when those departments work together.", st("The customer's experience depends on how the work fits together across departments.")],
["And that difference is at the heart of Business Process Management, or BPM.", null],
["BPM is about managing how work moves across an organisation to produce results that customers actually value.", t("What this course explores", "Business Process Management examines how organisations manage work across departments to deliver valuable customer outcomes.")],
["We'll explore that idea through a hotel group called Qasr Hospitality, which we'll follow throughout the term.", null],
["Qasr operates fourteen hotels and resorts, with three thousand one hundred employees serving its guests.", t("Our running case", "Qasr Hospitality Group operates 14 hotels and resorts and employs 3,100 people.")],
["Our story takes us to Qasr Marina, where a business traveller arrives after a delayed flight.", null],
["Her evening will help us understand why apparently successful departments can still produce an unsuccessful customer experience.", st("The Qasr Marina guest's experience will help us understand the difference between departmental performance and process performance.")],
["As we follow her, you'll learn to recognise a business process and identify exactly where it begins and ends.", it(1, 4, "target", "Recognise a process", "You will be able to define a business process and identify its starting and ending points.")],
["You'll also discover why problems arise between departments, even when each department meets its own performance targets.", it(2, 4, "link", "Understand the performance gap", "You will explain why a customer can suffer even when every department meets its targets.")],
["Then we'll explore how organisations manage complete customer journeys instead of concentrating only on separate departmental responsibilities.", it(3, 4, "users", "Understand process-centred organisations", "You will describe how organisations manage work across departments to improve customer outcomes.")],
["And we'll examine what BPM really involves, how it differs from individual improvement projects, and how organisations assess process maturity.", it(4, 4, "layers", "Understand BPM and maturity", "You will distinguish ongoing process management from individual improvement projects and explain process maturity.")],
["Together, these ideas support our course outcome K1, which asks you to analyse how organisations use BPM today.", st("K1: Analyse the utilization of Business Process Management in today's business environment.")],
["You don't need to memorise everything immediately, because we'll build your understanding through the same unfolding story.", null],
["For now, remember that our guest doesn't care which department is responsible for her difficulty.", null],
["She simply wants the right room, without unnecessary waiting or confusion.", q("What is the complete result the guest is actually waiting for?")],
["And that brings us to our next question: what exactly is the process that should deliver that result?", null]
]
},
{
title: "A process, in plain words",
sec: "O1a",
lines: [
["Let's return to our traveller at Qasr Marina, standing at reception after her delayed flight.", t("Understanding a business process", "Follow the guest's complete journey, rather than looking at one employee's job.")],
["The receptionist is trying to help, but the guest's booking involves information held by several departments.", null],
["Reservations has the booking, the revenue office holds the corporate rate, and housekeeping knows whether the room is ready.", dg("Several teams contribute", D.flow(["Reservations", "Revenue|office", "Housekeeping", "Front|desk", "+Guest in|room"]), "Several departments must contribute before the guest can reach the correct room.")],
["Now imagine asking the receptionist what her job involves, and she'll probably describe checking reservations and issuing keys.", null],
["That's useful work, but it doesn't describe everything the guest needs before she can settle into her room.", st("The receptionist's individual tasks are only part of the guest's complete experience.")],
["To understand the whole situation, we need to look beyond the receptionist's desk.", null],
["We need to follow the work from the moment the guest asks to check in until she reaches her room.", dg("The complete check-in journey", D.flow(["Guest at|desk", "Find|booking", "Confirm|rate", "Check room|status", "+Guest in|room"], { bracket: [0, 4, "The check-in process"] }), "The check-in process begins when the guest approaches reception and ends when she reaches the correct room.")],
["That connected journey is what we mean by a business process.", null],
["More precisely, a business process is a set of activities that together produce an outcome of value to a customer.", st("A business process is a set of activities that together produce an outcome of value to a customer.")],
["Notice how the definition focuses on the result, rather than the department performing the work.", null],
["For our traveller, that valuable result is being settled quickly in the correct room.", [cmp("a", "The customer", "The arriving guest needs a room that meets her booking."), cmp("b", "The valuable outcome", "The guest reaches the correct room without unnecessary delay.")]],
["But how do we recognise the complete process when we're looking at a complicated organisation?", null],
["Think about the moment our guest approaches reception and asks to check in.", null],
["That request is the trigger, which simply means the event that starts the process.", it(1, 3, "flag", "The trigger", "The guest's request to check in starts the process.")],
["Without that starting event, there's no particular guest journey for us to follow.", null],
["Once she makes her request, employees begin checking the booking, confirming the rate, and verifying room availability.", dg("Work begins after the trigger", D.flow(["*Guest|requests", "Booking|checked", "Rate|confirmed", "Room|verified", "Guest|settled"]), "The guest's request triggers a connected sequence of activities that should produce a completed check-in.")],
["Those connected activities form the sequence, which is the work performed between the starting event and the final result.", it(2, 3, "route", "The sequence", "The sequence connects booking verification, rate confirmation, room checking, and completion of check-in.")],
["And here's something worth noticing: the sequence doesn't belong entirely to one employee or department.", null],
["Information moves between teams, and each team contributes something needed by the next.", dg("Work crosses departments", D.lanes(["Front desk", "Revenue", "Housekeeping"], [[0, "Request"], [0, "Booking"], [1, "Rate"], [2, "Room"], [0, "Key"]]), "The guest's check-in depends on connected work across the front desk, revenue office, and housekeeping.")],
["When work passes from one team to another, we call that transfer a handoff.", null],
["These crossings between functions help us recognise the process as something broader than one team's task list.", st("A business process crosses functions because several teams contribute to the customer's final outcome.")],
["But even after everyone completes their assigned work, we still need to ask whether the guest received what she wanted.", null],
["That's why a process needs a defined end state, meaning the result that tells us the work is complete.", it(3, 3, "check", "The end state", "The check-in process ends when the guest is settled in the correct room.")],
["Handing over a key might finish the receptionist's task, but it doesn't necessarily finish the guest's journey.", null],
["Imagine receiving that key, walking upstairs, and discovering that housekeeping hasn't released the room yet.", iss("The receptionist has handed over the key, but the guest still cannot use the room.", "The outcome is missing")],
["Would you honestly say your check-in was complete, simply because the receptionist finished her work?", q("Has the process succeeded if the guest receives a key but cannot enter a ready room?")],
["Of course not, because the customer still hasn't received the outcome that gives the process its purpose.", null],
["This is why Jeston, whose textbook guides our course, offers such a practical test.", null],
["If you cannot identify the customer and the outcome they receive, you haven't properly identified the process.", st("Jeston's test: Identify the customer and the valuable outcome before claiming you have identified a process.")],
["Let's apply that test to our traveller, rather than getting distracted by departmental job descriptions.", null],
["Our customer is the arriving guest, and her expected outcome is reaching the correct room quickly.", [cmp("a", "Who receives the value?", "The guest arriving at Qasr Marina."), cmp("b", "What value does she receive?", "She reaches the correct room quickly and can begin her stay.")]],
["So we've discovered that a process connects a trigger, a sequence of activities, and a defined customer outcome.", null],
["And because that journey crosses departments, understanding it requires looking beyond individual jobs.", null],
["Now we're ready for another important question: how much of that journey should our process map actually show?", q("How detailed should the process map be, and where should its boundaries lie?")]
]
},
{
title: "Levels and boundaries",
sec: "O1b",
lines: [
["Now that we understand the guest's complete journey, let's imagine Qasr's managers gathering to draw their check-in process.", t("Levels and boundaries", "A useful process map must show the right level of detail and the complete customer outcome.")],
["The front-desk manager begins describing the entire arrival experience, while another employee explains how to open the booking portal.", null],
["Both descriptions are correct, but they're describing very different sizes of work.", iss("Two employees describe different amounts of work and cannot agree on what their process map should contain.", "Different levels")],
["And unless they agree on the level of detail, their discussion could continue without producing a useful map.", st("People must agree on the level of detail before they begin drawing a process map.")],
["To see why, imagine looking at Qasr Hospitality from high above, where you can see everything the group does.", null],
["At that broadest level, we have the value chain, meaning the organisation's overall work of creating value for customers.", dg("The value chain", D.hier(hierRows, 0), "At the broadest level, Qasr Hospitality's value chain is serving its guests.")],
["But serving guests involves many different journeys, and our traveller's arrival is only one of them.", null],
["When we focus on checking a guest in, we're looking at a process within that larger value chain.", dg("The check-in process", D.hier(hierRows, 1), "Checking a guest in is one complete process within Qasr's broader guest-service value chain.")],
["Now suppose the managers want to understand why confirming a corporate reservation takes so much effort.", null],
["They can move closer and examine verifying the booking, which is a sub-process, or a smaller connected part of check-in.", dg("The booking sub-process", D.hier(hierRows, 2), "Verifying the booking is a sub-process within the larger check-in process.")],
["Inside that booking verification work, someone must check the agreed room rate and the payment guarantee.", null],
["That particular piece of work is an activity, meaning a defined piece of work within the sub-process.", dg("A booking verification activity", D.hier(hierRows, 3), "Checking the rate and payment guarantee is an activity within booking verification.")],
["And if we look even more closely, an employee might need to open the corporate account portal.", null],
["Opening that portal is a task, meaning one specific action performed as part of the activity.", dg("A single task", D.hier(hierRows, 4), "Opening the corporate account portal is one task within the rate-checking activity.")],
["Notice how nothing about the guest has changed, even though we've moved from the organisation's purpose to one computer action.", null],
["We're simply looking at the same work through different levels of detail.", dg("The complete hierarchy", D.hier(hierRows, -1), "The value chain contains processes, processes contain sub-processes, sub-processes contain activities, and activities contain tasks.")],
["So before anyone starts drawing, the team should agree on exactly which level they're trying to understand.", st("Agree on the process level before modelling, because different levels answer different questions.")],
["Otherwise, someone describing the whole check-in journey may argue with someone describing how to open a portal.", null],
["Now there's another decision that matters just as much as the level of detail.", q("Where should the check-in process begin, and where should it end?")],
["We call this decision the process boundary, meaning the starting and ending points of the work we're studying.", null],
["Imagine Qasr decides its check-in process begins only when the receptionist finds the guest's reservation.", null],
["That sounds reasonable until we remember that the guest may already have waited in a queue.", iss("A boundary beginning with booking verification leaves the guest's earlier waiting time outside the process map.", "The boundary starts too late")],
["If the queue creates a major delay, that narrow boundary hides an important part of the problem.", null],
["Now imagine the managers decide check-in ends the moment the receptionist hands over the room key.", null],
["Our traveller walks upstairs, discovers that her room isn't ready, and has to seek help again.", iss("A boundary ending with key handover misses the guest's discovery that her room is not ready.", "The boundary ends too early")],
["The receptionist's task may be complete, but the customer's desired result is still missing.", null],
["That's why our boundary should begin when the guest approaches reception and end when she reaches the correct room.", dg("The customer-centred boundary", D.flow(["Guest at|desk", "Find|booking", "Confirm|rate", "Room|ready?", "+Guest in|room"], { bracket: [0, 4, "The check-in process"] }), "The check-in boundary includes the guest's arrival at reception and continues until she reaches the correct room.")],
["And it gives everyone a shared understanding of what successful check-in actually means.", st("A useful boundary includes the work that affects the customer's outcome, rather than stopping at a department's final task.")],
["Pause for a moment and picture our guest holding a key outside a room she cannot enter.", null],
["If your process map says everything is finished, what important part of reality have you left out?", q("Does your process boundary capture the customer's actual outcome?")],
["We'll return to these mapping decisions in Weeks 6 and 8, when we examine processes in greater detail.", st("The skills of choosing a process level and drawing its boundaries return in Weeks 6 and 8.")],
["For now, remember that the level determines how closely we look, while the boundary determines which work we include.", null],
["And with those decisions clear, we're ready to investigate why our traveller's check-in went wrong despite everyone's efforts.", null]
]
}
],
      },
      {
        id: "l2",
        title: "Why good departments can still fail you",
        sections: [
{
title: "One guest, nine departments",
sec: "O2a",
lines: [
["Let's return to Qasr Marina, where our business traveller is about to discover how complicated a simple check-in can become.", t("Qasr Marina hotel, 7:40 in the evening", "One guest, nine departments")],
["It's seven forty in the evening, and she's finally reached the hotel after a delayed flight.", null],
["She's tired, and all she wants is to settle into the room her company arranged.", st("A business traveller arrives at Qasr Marina after a delayed flight.")],
["Her company booked through a travel agency, using a special corporate rate agreed with Qasr Hospitality.", null],
["But when the receptionist opens her reservation, that agreed rate isn't visible on the front-desk screen.", iss("The receptionist cannot see the guest's agreed corporate rate.", "Hidden information")],
["The receptionist wants to help, but the information she needs is scattered across different departments.", null],
["Reservations holds the booking, while the revenue office keeps the corporate rate agreement in another system.", null],
["Housekeeping maintains room availability in a separate system, and finance holds the billing instructions in yet another.", dg("Four separate information systems", D.flow(["~Bookings", "~Rates", "~Room|status", "~Billing"]), "Reservations, revenue, housekeeping, and finance hold different information needed for the same guest.")],
["So the receptionist begins searching, checking, calling, and waiting for information that should support one simple arrival.", null],
["By the time the desk interaction finishes, our traveller has spent twenty-three minutes waiting through the check-in work.", iss("The guest spends 23 minutes at the desk while employees search, confirm, and transfer information.", "23 minutes")],
["She's also been asked to show her passport twice, even though she's already provided her details.", null],
["And when she finally receives her key, she discovers that her room isn't ready yet.", iss("The guest shows her passport twice and receives a room that is not ready.", "An incomplete check-in")],
["Her experience is so disappointing that she eventually rates her stay four out of ten.", fm("The guest's feedback score", "4", "10")],
["Now pause for a moment and consider who you would hold responsible for this experience.", q("Which department failed the guest?")],
["You might immediately blame reception, because that's where she spent those frustrating twenty-three minutes.", null],
["But the front desk actually met its published standard of ninety seconds for each individual transaction.", it(1, 3, "check", "Front desk performance", "Each individual transaction met the 90-second standard, although the guest needed several transactions and waited between them.")],
["The problem is that she needed several transactions, with searching, calls, and waiting between them.", null],
["So meeting a ninety-second transaction target didn't prevent her complete desk experience from taking twenty-three minutes.", [cmp("a", "One transaction", "Each single transaction took 90 seconds, which met the front desk's standard.", "up"), cmp("b", "Her whole time at the desk", "She needed several transactions with waiting in between, so it took 23 minutes.", "down")]],
["Perhaps the revenue office was responsible, since the receptionist had to contact it about the corporate rate.", null],
["Yet revenue answered within its ten-minute service level, so that department also met its published target.", it(2, 3, "check", "Revenue office performance", "The revenue office answered within its 10-minute service level.")],
["And housekeeping released the room within its forty-five-minute target, even though the guest received a room that wasn't ready.", it(3, 3, "check", "Housekeeping performance", "Housekeeping met its 45-minute release target, but the guest was still given a room that was not ready.")],
["Here's the uncomfortable discovery: every department passed its own performance test, while the customer had a terrible evening.", [cmp("a", "Departmental performance", "The departments met their individual published targets.", "up"), cmp("b", "Customer experience", "The guest waited 23 minutes at the desk and rated her stay 4 out of 10.", "down")]],
["How can those apparently contradictory results both be true at the same time?", null],
["The answer lies in the difference between how organisations manage departments and how customers experience their services.", null],
["Departments are managed vertically, meaning each one reports performance through its own management structure.", dg("The vertical view", D.org("silo"), "Each department concentrates on its own responsibilities and reports performance through its management structure.")],
["But customers move horizontally, meaning their journeys depend on work crossing several departments and their boundaries.", dg("The horizontal journey", D.org("process"), "The guest's experience crosses departmental boundaries rather than remaining inside one department.")],
["Our traveller doesn't experience nine separate departments as nine separate successes; she experiences one difficult arrival.", null],
["And that's why excellent departmental results can coexist with a process that fails the customer.", st("Every department can meet its targets while the complete customer journey still fails.")],
["We've now discovered the central problem, but we still need to understand exactly where the time disappears.", null],
["So let's follow those twenty-three minutes and examine what happens whenever work moves between teams.", null]
]
},
{
title: "Handoffs and the end-to-end measure",
sec: "O2b",
lines: [
["Now let's return to our traveller's twenty-three minutes at reception and examine where that time actually went.", t("Exhibit 1 from the Qasr case", "Where the guest's 23 minutes at the desk went")],
["Imagine standing beside her, watching each activity while the receptionist tries to complete her check-in.", null],
["She spends six minutes in the queue before the receptionist can begin helping her.", null],
["Then finding her reservation across two systems takes four minutes, followed by three minutes re-entering guest information.", dg("The first 13 minutes", D.bars(exhibit, { show: 3 }), "Queuing takes 6 minutes, locating the booking takes 4 minutes, and re-entering details takes 3 minutes.")],
["Already, thirteen minutes have passed, and she still hasn't received the room she came for.", null],
["The receptionist then spends seven minutes calling the revenue office to confirm the agreed corporate rate.", null],
["Another two minutes go into confirming whether housekeeping has released the room.", dg("The next 9 minutes", D.bars(exhibit, { show: 5 }), "Confirming the corporate rate takes 7 minutes, and checking the room release takes another 2 minutes.")],
["Finally, handing over the key and directions takes just one minute.", null],
["That final minute is the only step the exhibit classifies as directly adding value for the guest.", dg("The complete 23-minute exhibit", D.bars(exhibit, { hiNo: true }), "Only the final minute, handing over the key and directions, is classified as directly adding value.")],
["So why did something requiring one minute of directly valuable work consume twenty-three minutes at the desk?", q("Where did the other 22 minutes go?")],
["Much of the difficulty comes from handoffs, which are moments when work passes between people or departments.", null],
["Each transfer can introduce waiting, missing information, or uncertainty about who should act next.", dg("The handoffs between teams", D.lanes(["Front desk", "Revenue", "House-|keeping"], [[0, "Queue"], [0, "Find|booking"], [1, "Confirm|rate"], [0, "Re-key"], [2, "Room|released?"], [0, "Key"]]), "The guest's check-in involves transfers between the front desk, revenue office, and housekeeping.")],
["Think about the receptionist waiting for revenue to confirm information that isn't available on her screen.", null],
["Time leaks away while the work waits, even though nobody may be deliberately delaying it.", iss("Work waits for another department to respond, increasing the customer's total waiting time.", "Time is lost")],
["Information can disappear or become disconnected too, forcing employees to ask questions or enter details again.", iss("Information is scattered across systems, so employees must search for it or enter it again.", "Information is lost")],
["And responsibility can become unclear when everyone assumes another department is handling the remaining problem.", iss("Each department may assume another team is responsible for completing the guest's journey.", "Responsibility is lost")],
["You've probably experienced something similar when renewing an identity card and moving between several service counters.", dg("An everyday handoff", D.flow(["Counter 1", "!Wait", "Counter 2", "!Repeat|details", "Counter 3"]), "Moving between service counters can create repeated waiting and requests for the same information.")],
["Now there's another danger, and it appears when departments try to improve their own performance independently.", null],
["We call this local optimisation, meaning making one part of the work more efficient without considering the complete process.", t("Local optimisation", "Improving one department can make the whole flow worse.")],
["Imagine Qasr's sales team begins booking rooms faster than housekeeping can prepare them.", null],
["Sales performance improves, but the additional bookings can create a growing queue of rooms awaiting preparation.", dg("When the queue moves downstream", D.flow(["*Sales books|faster", "!Rooms not|ready", "!Queue|grows", "Guest|waits"]), "Faster bookings can create a backlog when housekeeping cannot prepare rooms at the same pace.")],
["So local optimisation can make the whole flow worse, even when the department making the change becomes more efficient.", st("Improving one department does not necessarily improve the complete customer journey.")],
["That's why we need an end-to-end measure, meaning a measure covering the customer's journey from trigger to outcome.", null],
["For check-in, that means measuring from the guest's arrival at reception until she's settled in the correct room.", dg("Measure the complete journey", D.flow(["Guest|arrives", "Front|desk", "Revenue", "House-|keeping", "+Guest in|room"], { bracket: [0, 4, "End-to-end check-in"] }), "The end-to-end measure starts when the guest approaches reception and ends when she reaches the correct room.")],
["Remember that the twenty-three minutes describe only the desk portion, not the entire journey into a ready room.", null],
["Our traveller still reached a room that wasn't ready afterwards, so her complete experience extended beyond that desk measure.", iss("The 23-minute desk interaction does not capture the additional problem of reaching a room that was not ready.", "The complete outcome is missing")],
["And in many organisations, almost nobody owns that complete end-to-end measure across departmental boundaries.", st("The customer experiences the complete process, but responsibility for measuring it often remains fragmented.")],
["So the lesson is simple: departmental speed cannot tell us whether the customer actually received a good outcome.", null],
["Next, we'll explore how process-centred organisations manage that complete journey rather than leaving it between departments.", null]
]
}
],
      },
      {
        id: "l3",
        title: "The process-centred organisation",
        sections: [
{
title: "Four things they do differently",
sec: "O3a",
lines: [
["Let's return to Qasr Marina, where the management team is reviewing what happened to our business traveller.", t("The morning after the guest's complaint", "What would a process-centred Qasr do differently?")],
["She arrived exhausted after a delayed flight, waited twenty-three minutes at reception, and received a room that wasn't ready.", null],
["Her feedback score was four out of ten, yet every department had met its own performance target.", iss("Every department met its target, but the guest waited and received a room that was not ready.", "A failed customer experience")],
["The general manager looks around the meeting room and asks who was responsible for her complete check-in experience.", null],
["The front-desk manager explains what reception completed, while revenue and housekeeping describe their own successful performance.", null],
["But nobody can answer the general manager's question about responsibility for the entire journey.", q("Who was responsible for the guest's complete journey?")],
["And that's when the management team begins to understand what a process-centred organisation would do differently.", null],
["A process-centred organisation manages the complete flow of work across departments, rather than treating each department as a separate success.", t("A process-centred organisation", "The customer's complete journey becomes a shared management responsibility.")],
["Imagine Qasr appointing someone responsible for the entire check-in process, from the guest's arrival until she's settled.", null],
["That person becomes the process owner, meaning someone accountable for the complete flow and empowered to improve it.", it(1, 4, "key", "A named process owner", "One person is accountable for the complete check-in journey and has authority to improve work across departments.")],
["She can work across reception, revenue, and housekeeping instead of being limited to one department's responsibilities.", dg("One owner for the guest's journey", D.flow(["Guest at|desk", "Booking|checked", "Rate|confirmed", "Room|ready", "+Guest|settled"], { bracket: [0, 4, "The check-in process owner"] }), "The process owner is responsible for the complete journey from reception to the guest's ready room.")],
["But giving someone responsibility isn't enough unless the organisation also changes how it judges success.", null],
["Qasr currently celebrates individual targets, including ninety seconds per front-desk transaction and housekeeping's forty-five-minute release standard.", null],
["A process-centred Qasr would also measure the complete time from the guest's arrival until she reaches her room.", it(2, 4, "gauge", "End-to-end performance", "Qasr measures the time from the guest's arrival at reception until she reaches the correct room.")],
["That measure would reveal delays that individual departmental reports cannot show.", null],
["Now imagine the owner discovers that disconnected booking and rate systems repeatedly delay corporate guests.", null],
["If improvement budgets remain locked inside departments, she may struggle to fix the connection between those systems.", iss("Separate departmental budgets can prevent improvements that require several teams to work together.", "Fragmented improvement funding")],
["A process-centred organisation directs improvement money toward the complete process, rather than funding only isolated departmental changes.", it(3, 4, "chart", "Money follows the process", "Improvement budgets support the complete customer journey rather than only individual departments.")],
["And there's another change that matters whenever employees make everyday decisions.", null],
["Imagine the receptionist understanding how revenue confirms rates and how housekeeping communicates room readiness.", null],
["She can recognise how her decisions affect the guest's journey beyond the reception desk.", it(4, 4, "users", "Staff understand the whole", "Employees understand the complete process and how their work affects the customer's final outcome.")],
["That broader understanding helps employees recognise problems that would otherwise remain hidden between departments.", null],
["You can see the same approach in an online shop that manages returns as one complete customer journey.", null],
["Its returns owner follows the request from the customer's click through collection, warehouse checking, and the final refund.", dg("An online return managed as one process", D.flow(["Click|Return", "Courier|collects", "Warehouse|checks", "Finance|refunds", "+Money|back"], { bracket: [0, 4, "The returns owner"] }), "One process owner is responsible for the complete return journey, including collection, checking, and refund.")],
["Instead of celebrating how many parcels the warehouse scans, the shop measures how long customers wait for their refunds.", [cmp("a", "Departmental measure", "The warehouse measures how many parcels it scans."), cmp("b", "End-to-end measure", "The organisation measures how many days customers wait for their refunds.")]],
["Now here's something important: Qasr doesn't need to abolish its departments to manage processes properly.", null],
["Reception, revenue, housekeeping, and finance can remain in the organisation chart, with their specialist responsibilities intact.", null],
["Instead, the process view is laid over that structure, a bit like a road map laid over a list of towns.", dg("The process view across departments", D.org("process", { from: "Guest arrives", to: "Guest settled", depts: ["Front desk", "Revenue", "Housekeeping", "Finance"], top: "General Manager" }), "The departments remain in place while the guest's complete journey is managed across them.")],
["So a process-centred Qasr would combine genuine ownership, complete measures, shared improvement funding, and employees who understand the whole journey.", null],
["But before we celebrate that solution, there's a dangerous mistake Qasr could make when appointing its process owner.", q("What happens if the process owner has responsibility but no authority to change anything?")]
]
},
{
title: "Two lenses, and a trap",
sec: "O3b",
lines: [
["Now imagine Qasr's general manager asking everyone to examine the same guest complaint from two different perspectives.", t("Two ways to understand an organisation", "The functional view and the process view")],
["The department managers begin by describing how efficiently their individual teams performed during the traveller's arrival.", null],
["This is the functional view, which looks at the organisation through its separate departments and specialist responsibilities.", [cmp("a", "The functional view", "The organisation is examined through its separate departments."), cmp("b", "The process view", "The organisation is examined through the customer's complete journey.")]],
["From that perspective, reception met its transaction target, revenue answered promptly, and housekeeping met its release standard.", null],
["Those figures tell us something useful about each department, but they don't explain the guest's complete experience.", st("Each department's report looks good, but none of them describes the guest's whole evening.")],
["Now the general manager asks everyone to follow the traveller from reception until she reaches her room.", null],
["This is the process view, which follows connected work across departments from the customer's starting event to the final outcome.", dg("The journey across departments", D.org("process"), "The process view follows the guest's complete journey across departmental boundaries.")],
["Instead of examining departmental efficiency alone, the team now considers the complete time, service quality, and cost of serving her.", [cmp("a", "Functional performance measures", "Each department measures its own efficiency."), cmp("b", "Process performance measures", "The complete process is measured through cycle time, quality, and cost to serve.")]],
["Cycle time means the total elapsed time needed to complete the process, including the periods when work waits.", null],
["And cost to serve means the resources and expenditure required to deliver the customer's complete service.", null],
["The functional view encourages managers to improve their own activities, while the process view encourages improvement of the complete flow.", [cmp("a", "Functional improvement", "Managers improve their departments separately."), cmp("b", "Process improvement", "Managers improve the complete flow across departments.")]],
["That difference also changes how directly managers see the customer.", null],
["A departmental manager may see customer needs indirectly through internal targets, while a process owner follows the actual customer outcome.", [cmp("a", "Functional view of the customer", "Customer needs are seen indirectly through departmental performance."), cmp("b", "Process view of the customer", "The customer's complete experience is examined directly.")]],
["Now think about our traveller's disappointing evening and the excellent departmental reports presented afterward.", null],
["That contradiction illustrates the functional view's typical failure: local wins can produce a global loss.", iss("Each department meets its targets, but the complete customer journey fails.", "Local wins, global loss")],
["But the process view has a trap of its own, and Qasr is about to encounter it.", null],
["Imagine the general manager proudly announces that someone has been appointed as the new check-in process owner.", t("The trap of the process view", "Qasr names a check-in process owner, and everyone believes the problem is solved.")],
["Everyone applauds, believing the hotel has finally solved its problem of fragmented responsibility.", null],
["Yet when she investigates the delays, the new owner discovers that she cannot change the corporate rate system.", dg("A process owner without authority", D.flow(["~Rate|system", "~Housekeeping|schedule", "~Team|targets"]), "The process owner cannot change the systems, schedules, or targets contributing to the guest's difficulties.")],
["She also cannot adjust housekeeping schedules or change the departmental targets that encourage disconnected decisions.", null],
["So although she's accountable for check-in, the managers controlling its activities can refuse her proposed improvements.", iss("The process owner is accountable for the outcome but cannot change the work causing the problem.", "Ownership without authority")],
["This is ownership without authority, meaning responsibility for a process without the power needed to manage it.", null],
["And here's the surprising part: that arrangement can be worse than having no process owner at all.", st("A process owner without real authority can be worse than having no owner.")],
["Why would giving someone responsibility actually make the situation more dangerous?", q("Why can naming a powerless process owner make the problem harder to solve?")],
["Because everyone now assumes the check-in problem belongs to someone who is already taking care of it.", null],
["Other managers may stop questioning the delays, even though the appointed owner cannot remove their causes.", null],
["The organisation gains the appearance of accountability without gaining the ability to improve the process.", st("A title without authority creates the appearance of accountability while leaving the underlying problems unchanged.")],
["Real ownership therefore requires authority over the flow of work, the performance measures, and the improvement budget.", t("Real process ownership", "The owner needs authority over the flow of work, the measures, and the budget.")],
["For Qasr, that means being able to coordinate how departments work together and influence the targets guiding their decisions.", null],
["It also means having access to the resources needed to improve connections between systems and teams.", null],
["So remember that the functional lens helps us understand individual departments, while the process lens reveals the complete customer journey.", [cmp("a", "The functional lens", "It shows how well each department does its own part."), cmp("b", "The process lens", "It shows the guest's whole journey across the departments.")]],
["Neither perspective should disappear, but the process owner must have genuine authority if the whole journey is to improve.", null],
["And that raises our next question: is fixing Qasr's check-in once enough, or must someone keep managing it afterward?", q("Should Qasr improve check-in once, or manage its performance continuously?")]
]
}
],
      },
      {
        id: "l4",
        title: "BPM, BPI, and process maturity",
        sections: [
{
title: "A project, or a discipline?",
sec: "O4a",
lines: [
["Let's return to Qasr Marina, where the management team has finally decided to fix the troubled check-in process.", t("Qasr Marina: fixing check-in", "What happens after the improvement project finishes?")],
["Our business traveller's disappointing evening has made the problem impossible to ignore, especially after her feedback score of four out of ten.", null],
["The general manager brings reception, revenue, housekeeping, and finance together to examine what went wrong.", dg("The improvement team", D.org("process"), "Qasr brings its departments together to improve the guest's complete check-in journey.")],
["They discover that employees waste time searching disconnected systems, repeating information, and waiting for confirmation from other departments.", null],
["So the team begins an improvement project, with a clear problem to solve and a definite finishing point.", null],
["Imagine they simplify the booking checks, reduce repeated data entry, and improve communication about room readiness.", dg("The proposed improvement", D.flow(["Booking|found", "Rate|confirmed", "Room|ready", "+Guest|settled"]), "The improvement project simplifies the connections between booking verification, rate confirmation, and room readiness.")],
["These changes are intended to prevent another guest from experiencing the same frustrating arrival.", null],
["After the new arrangements are introduced, the project team completes its work and prepares to close the project.", null],
["This is Business Process Improvement, or BPI, which means a project designed to improve a particular business process.", dg("Business Process Improvement", D.cycle("line"), "BPI is a project that improves a process and then reaches a defined finish.")],
["The project has a beginning, a specific improvement objective, and an end when its work is completed.", null],
["But here's the question I want you to consider before everyone congratulates the project team.", q("Who will keep watching check-in after the improvement project closes?")],
["Imagine the employees return to their normal departmental routines, and nobody continues monitoring the complete guest journey.", null],
["Over time, new staff arrive, systems change, and departments begin making decisions independently again.", null],
["The original improvements may gradually disappear because nobody is responsible for keeping the process working well.", iss("Without continuing ownership and measurement, Qasr's check-in improvements may gradually disappear.", "The gains fade")],
["Perhaps three years later, Qasr launches another project to solve problems remarkably similar to those it already addressed.", null],
["That's the danger when an organisation relies only on occasional improvement projects.", st("An organisation relying only on BPI may need to improve the same process again every few years.")],
["Now imagine Qasr making a different decision when the project finishes.", null],
["Instead of closing the project and forgetting the process, it keeps a named owner responsible for check-in.", null],
["That owner regularly examines how long guests wait, whether rooms are ready, and whether the complete journey meets expectations.", dg("Business Process Management", D.cycle("loop"), "BPM continues through ownership, measurement, governance, and improvement long after individual projects finish.")],
["When performance begins deteriorating, the owner investigates and coordinates action before the same problems become established again.", null],
["This continuing approach is Business Process Management, or BPM, a management discipline that governs processes as part of everyday organisational life.", t("Business Process Management", "BPM is a continuing management discipline, not a project that closes after an improvement.")],
["Governance means having clear responsibility, measures, and decision-making arrangements that keep the process under control.", null],
["So BPM includes BPI projects whenever improvement is needed, but it doesn't disappear when those projects end.", st("BPM includes BPI projects and adds continuing ownership, measurement, and governance.")],
["Think about your own health, because the difference becomes easier to understand through something familiar.", null],
["A crash diet resembles BPI because it pursues a particular result over a limited period.", cmp("a", "A crash diet resembles BPI", "A short-term effort produces an improvement, but the effort eventually ends.", "down")],
["But if you return to your old habits afterward, the weight may gradually come back.", null],
["A healthy routine resembles BPM because you keep monitoring your habits and making adjustments over time.", cmp("b", "A healthy routine resembles BPM", "Continuing habits, regular checks, and adjustments help preserve the improvement.", "up")],
["You can still make a focused improvement when necessary, but that effort sits inside your continuing routine.", null],
["That's exactly how an improvement project should fit inside Qasr's ongoing management of check-in.", null],
["The difference is governance, which determines who keeps watching and acting after the project team leaves.", st("BPI fixes a process through a project, while BPM continues governing that process after the project ends.")],
["This distinction matters in your assessment and explains why Weeks 13 and 14 examine lasting value and sustainable performance.", null],
["But even with continuing management, Qasr must ask whether its check-in process is ready for more advanced improvements.", null],
["And that brings us to a new question about how mature the process really is.", q("How mature is Qasr's check-in process, and what improvements can it realistically support?")]
]
},
{
title: "How mature is the process?",
sec: "O4b",
lines: [
["Now imagine Qasr's new process owner reviewing the check-in operation before deciding what to improve next.", t("Diagnosing Qasr's check-in process", "Process maturity helps managers choose improvements that the process can actually support.")],
["So she begins investigating how consistently employees perform the work, how it is documented, and whether anyone measures the results.", null],
["What she's investigating is process maturity, usually described in five levels, which show how developed, consistent and controlled a process has become.", dg("The maturity journey", D.stairs(-1), "Process maturity describes the development of a process from Initial through Repeatable, Defined, Managed, and Optimising.")],
["Imagine discovering that check-in depends heavily on whichever receptionist happens to be working that evening.", null],
["Experienced employees know how to solve problems through personal contacts, while newer colleagues struggle with the same situations.", null],
["This is level one, called Initial, where the work depends on heroic individual effort rather than a reliable way of working.", dg("Initial", D.stairs(0), "At Initial, results depend heavily on individual effort, and performance varies between employees.")],
["Now imagine the team documenting how bookings should be verified and how room readiness should be confirmed.", st("The team writes down how bookings are verified and how room readiness is confirmed.")],
["Employees begin following these written procedures most of the time, making the work more predictable.", null],
["The process has climbed to level two, called Repeatable, meaning it's written down and followed most of the time.", dg("Repeatable", D.stairs(1), "At Repeatable, employees have written procedures and follow them most of the time.")],
["But Qasr operates fourteen hotels and resorts, and those properties may still use different versions of the procedure.", null],
["So management works toward a common check-in method that can be used consistently throughout the group.", null],
["When the process is standardised across the organisation, it reaches level three, called Defined, where every hotel shares one way of working.", dg("Defined", D.stairs(2), "At Defined, the process is standardised across the organisation rather than varying between branches.")],
["And once that common method exists, managers can begin judging whether it performs as intended.", null],
["Imagine the process owner regularly reviewing complete check-in times and responding when results move away from agreed targets.", null],
["The process has reached level four, called Managed, where performance is measured and controlled against targets.", dg("Managed", D.stairs(3), "At Managed, the process is measured against targets, and managers respond when performance drifts.")],
["But Qasr's development doesn't have to stop with managers watching performance reports.", null],
["Imagine reception and housekeeping employees regularly identifying small improvements because they understand the process and its results.", st("Reception and housekeeping staff spot small improvements themselves, because they understand the whole process.")],
["They test better ways of working and continue refining the process rather than waiting for another major project.", null],
["That's level five, called Optimising, where the people doing the work keep improving it themselves.", dg("Optimising", D.stairs(4), "At Optimising, employees continually identify and implement improvements to the process they perform.")],
["Now pause and consider whether Qasr should immediately introduce advanced continuous improvement techniques into an undocumented check-in process.", q("Can a process improve continuously when employees haven't agreed on how the work should be performed?")],
["A process at Initial cannot reliably absorb advanced continuous improvement because there is no stable, documented method to improve.", iss("Advanced improvement techniques are unlikely to work when employees do not yet share a documented way of working.", "The process is not ready")],
["It needs documentation and a dependable routine before more sophisticated methods can become effective.", null],
["Think about teaching someone to drive, because you wouldn't begin with racing techniques before they understand the basics.", st("Choose improvements that match the process's current maturity, just as a new driver learns basic skills before advanced techniques.")],
["This is why maturity is a diagnosis, like a doctor's check-up, rather than a score managers should chase.", null],
["It tells you which improvements will work, and which ones the organisation will reject.", st("Maturity is a diagnosis that guides improvement choices, not a target to pursue for its own sake.")],
["And Qasr shouldn't assume that every process across its fourteen properties has the same maturity.", null],
["Check-in might still be Initial, while the group's billing process could already be Managed.", dg("Different processes, different maturity", D.stairs([0, 3], { alt: "Check-in is Initial while billing is Managed within the same hotel group." }), "Check-in may be Initial while billing is Managed, so each process requires its own assessment.")],
["The owner must therefore assess each process separately rather than assigning one maturity level to the entire company.", null],
["And she must support every maturity claim with evidence, because a level claimed without evidence is the most common misuse of these models.", iss("Claiming a maturity level without supporting evidence is a misuse of the maturity model.", "An unsupported claim")],
["Simply announcing that check-in is Managed doesn't make it true if nobody can demonstrate consistent measurement and control.", null],
["So Qasr's next step is to diagnose honestly, establish what is missing, and choose improvements appropriate to that maturity.", null],
["Now we're ready to examine the framework that helps organisations organise this improvement journey without treating it as a rigid checklist.", q("How can Qasr organise its BPM journey while remaining willing to revisit earlier decisions?")]
]
}
],
      },
      {
        id: "l5",
        title: "The road ahead, and your forum",
        sections: [
{
title: "A route, not a ratchet",
sec: "O4c",
lines: [
["Let's return to Qasr Marina, where the management team now understands that improving check-in once won't be enough.", t("Qasr Hospitality's journey ahead", "A BPM framework helps organisations organise improvement and sustain the results.")],
["Our business traveller's difficult evening revealed problems that crossed departments, systems, and responsibilities.", null],
["Qasr has begun thinking about process ownership, complete performance measures, and the maturity of its check-in arrangements.", null],
["But the general manager now faces a practical question about how to organise the work ahead.", q("How can Qasr turn its discoveries into lasting improvements?")],
["This is where our BPM framework becomes useful, because it provides a structured route through the improvement journey.", null],
["The framework contains ten phases, and we'll study one each week, from Week 5 through Week 14 of this course.", dg("The BPM framework", D.route([]), "The framework contains ten phases, studied from Week 5 through Week 14.")],
["Imagine Qasr beginning by asking how better guest experiences support the hotel group's wider business ambitions.", null],
["That conversation belongs to Organisation Strategy, where BPM work is connected to what the organisation wants to achieve.", dg("Connecting improvement to strategy", D.route([0]), "Organisation Strategy connects process improvement with the organisation's wider business objectives.")],
["But before changing check-in, Qasr also needs to understand how its important processes fit together.", null],
["That's the purpose of Process Architecture, which provides a structured picture of the organisation's processes and their relationships.", dg("Understanding the process landscape", D.route([0, 1]), "Process Architecture identifies the organisation's processes and how they fit together.")],
["Once that picture is clear, Qasr can prepare the improvement programme through the Launch Pad.", null],
["The Launch Pad establishes the practical foundations needed to begin the work properly.", dg("Preparing to begin", D.route([0, 1, 2]), "Organisation Strategy, Process Architecture, and the Launch Pad establish the foundations for the BPM programme.")],
["Now imagine the team returning to the reception desk to investigate exactly what happens during a guest's arrival.", null],
["In Understand, they examine the current process and investigate the causes of waiting, repeated information, and incomplete room preparation.", dg("Understanding the current process", D.route([3]), "Understand examines how the current process works and why its problems occur.")],
["What they discover gives them a basis for Innovate, where they design a better way of delivering check-in.", null],
["But even a promising design won't succeed unless the employees involved are prepared to work differently.", null],
["That's why People focuses on preparing those affected by the proposed changes.", dg("Designing and preparing for change", D.route([3, 4, 5]), "Understand investigates the current process, Innovate designs improvements, and People prepares those affected.")],
["Once the team knows what should change, it can move toward building and introducing the solution.", null],
["Develop turns the proposed design into something that can be put into operation.", null],
["Implement then puts that solution into practice, allowing Qasr to change how check-in actually works.", dg("Building and introducing improvements", D.route([6, 7]), "Develop builds the solution, while Implement puts it into operation.")],
["But installing a solution doesn't prove that the guest's experience has improved.", null],
["Qasr must examine the results through Realise Value, which checks whether the intended benefits have actually been achieved.", dg("Checking the benefits", D.route([8]), "Realise Value examines whether the implemented changes have delivered their intended benefits.")],
["And because those benefits can disappear over time, Sustainable Performance focuses on keeping the improvements working.", dg("Making the gains last", D.route([6, 7, 8, 9]), "Develop, Implement, Realise Value, and Sustainable Performance deliver the solution, verify its benefits, and sustain the gains.")],
["Throughout this journey, Qasr also needs Project Management, People Change Management, and Leadership.", null],
["These essentials support every phase rather than appearing as separate phases at the end.", dg("Support throughout the framework", D.route([], { band: true }), "Project Management, People Change Management, and Leadership support every phase of the BPM framework.")],
["Now here's something important about how Qasr should use this framework.", null],
["The phases provide an order for organising work, but they don't forbid the team from revisiting earlier decisions.", t("A route, not a ratchet", "The framework provides direction while allowing teams to revisit earlier work when they learn something new.")],
["Imagine the team reaching Understand and discovering that its original Process Architecture overlooked an important connection between departments.", null],
["Should everyone ignore that discovery simply because the architecture phase has already been completed?", q("Should Qasr continue with an incorrect process architecture just because that phase is finished?")],
["Of course not, because the team should return to Process Architecture and correct what it misunderstood.", dg("Returning when necessary", D.route([1, 3], { back: [3, 1], alt: "Understand returns to Process Architecture when new evidence reveals a mistake." }), "A discovery during Understand can require the team to revisit Process Architecture.")],
["That's why we describe the framework as a route rather than a ratchet.", null],
["A ratchet permits movement in only one direction, while a route allows you to go back when new information changes your understanding.", [cmp("a", "A ratchet", "A ratchet prevents returning to earlier work."), cmp("b", "A route", "A route allows teams to revisit earlier work when new evidence requires it.")]],
["Teams that treat the phases as boxes to tick can finish their projects while delivering systems nobody actually uses.", iss("Treating the framework as a rigid checklist can produce a completed system that employees do not use.", "Checklist thinking")],
["So Qasr's journey isn't simply about completing ten phases; it's about learning, improving, verifying value, and sustaining performance.", null],
["And that brings us back to the traveller whose disappointing evening started our entire Week 1 story.", null]
]
},
{
title: "Week 1 in four lines, and your forum",
lines: [
["Before we finish, I'd like you to return with me to that evening at Qasr Marina.", t("Bringing Week 1 together", "What one guest's experience teaches us about Business Process Management")],
["Our business traveller arrived after a delayed flight, hoping to reach her room without further complications.", null],
["Instead, she waited twenty-three minutes at reception, showed her passport twice, and received a room that wasn't ready.", null],
["Her feedback score was four out of ten, despite the departments meeting their individual performance targets.", iss("The guest's experience was poor even though the departments met their individual targets.", "The central problem")],
["Now think about how differently you understand that evening compared with when we began.", null],
["You can recognise check-in as a business process because connected activities produce an outcome the guest values.", it(1, 4, "route", "A process produces customer value", "The check-in process connects work across departments and ends when the guest reaches the correct room.")],
["It begins when she approaches reception and ends when she's settled in the correct room.", null],
["And because that journey crosses departments, examining individual jobs cannot explain everything she experienced.", null],
["That's why Qasr's excellent departmental reports didn't prevent a disappointing customer experience.", it(2, 4, "link", "Departmental success can hide process failure", "Every department can meet its targets while the complete customer journey still fails.")],
["The organisation needed someone to understand, measure, and manage the complete journey across departmental boundaries.", null],
["We then discovered why a process-centred organisation gives that journey a genuine owner with authority to improve it.", st("Process-centred organisations manage the complete customer journey through ownership, shared measures, and coordinated improvement.")],
["But appointing an owner isn't enough if that person cannot influence the work, measures, or improvement budget.", null],
["And even a successful improvement project won't protect the guest's experience forever unless someone continues managing the process.", it(3, 4, "loop", "BPM continues after improvement projects", "BPI improves a process through a project, while BPM continues ownership, measurement, and governance.")],
["That's the difference between BPI, a focused improvement project, and BPM, an ongoing management discipline.", null],
["We also learned that organisations need to understand how mature their processes are before choosing improvements.", it(4, 4, "chart", "Maturity guides improvement", "A maturity diagnosis identifies the improvements that a process can realistically support.")],
["A process without dependable procedures needs those foundations before advanced improvement techniques can work reliably.", null],
["And the BPM framework gives Qasr a route for organising improvement, checking the benefits, and sustaining performance.", null],
["So the real lesson isn't about making every department look successful on its own.", st("The real goal is to manage the complete flow of work so the customer receives the intended outcome.")],
["It's about ensuring that the complete process delivers what the customer actually needs.", null],
["Now I'd like you to apply that understanding to a different organisation facing a remarkably similar problem.", t("Your Week 1 forum", "The Complaint That Nobody Owned")],
["Our forum case takes us to Al Madar Logistics, where a client submitted a complaint that travelled through several departments.", null],
["The complaint passed through six departments, and every department met its own key performance indicator, or KPI.", dg("The complaint's journey", D.flow(["Account|manager", "Customer|service", "Operations", "Compliance", "Vendor|mgmt", "!Quality"]), "The complaint passed through six departments, and each department met its own KPI.")],
["Yet the client waited nineteen days for an answer, despite all those apparently successful departmental results.", iss("The client waited 19 days for an answer even though all six departments met their individual KPIs.", "19 days")],
["Does that sound familiar after everything we've discovered about our traveller's experience at Qasr Marina?", q("How can every department meet its KPI while a client's complaint remains unresolved for 19 days?")],
["As you examine the case, think about what happens when work moves between departments and nobody manages the complete journey.", null],
["Consider where responsibility might become unclear and what an end-to-end measure would reveal.", null],
["Then ask yourself what genuine process ownership would need to change to prevent the same problem from recurring.", q("Who should own the complaint from the client's request until the client receives an answer?")],
["For the forum, begin by posting your own answer before reading and responding to your classmates' contributions.", st("Post your own answer first, using the BPM ideas developed during Week 1.")],
["Afterward, reply to at least two classmates and engage seriously with the reasoning they present.", null],
["I also want you to respectfully disagree with at least one classmate, explaining your reasoning rather than simply saying they're wrong.", st("Reply to at least two classmates, and respectfully disagree with at least one by explaining your reasoning.")],
["Remember that thoughtful disagreement helps us examine assumptions and discover perspectives we might otherwise overlook.", null],
["And as you write, keep our tired business traveller in mind, because the underlying problem is remarkably similar.", null],
["Next week, we'll examine what makes an organisation decide to begin a BPM programme in the first place.", t("Next week", "What makes an organisation start a BPM programme")],
["For now, remember that a successful process isn't defined by how good its departments look, but by the outcome its customer receives.", null],
["That's the perspective I want you to carry into the rest of OPER621.", null]
]
}
],
      },
    ],
  };
  // Plain-text script for tools that expect it.
  COURSE.lessons.forEach((l) => l.sections.forEach((s) => (s.script = s.lines.map((x) => x[0]).join(" "))));
})();
